INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein IT-Betrieb gesetzlich verpflichtet, Recycling-Maßnahmen umzusetzen?', 2, '[{"text": "Ja", "correct": true, "because": "Kreislaufwirtschaftsgesetz (KrWG) fordert Recycling"}, {"text": "Nein", "correct": false, "because": "Gesetzliche Pflicht besteht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Recycling im IT-Betrieb die Abfallmenge reduzieren?', 2, '[{"text": "Ja", "correct": true, "because": "Wiederverwertung verringert Müll"}, {"text": "Nein", "correct": false, "because": "Reduktion ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alte IT-Geräte gemäß dem ElektroG recycelt werden?', 2, '[{"text": "Ja", "correct": true, "because": "ElektroG regelt Recycling von Elektrogeräten"}, {"text": "Nein", "correct": false, "because": "Pflicht ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Recycling im Betrieb Kosten verursachen?', 2, '[{"text": "Ja", "correct": true, "because": "Entsorgung und Prozesse kosten Geld"}, {"text": "Nein", "correct": false, "because": "Kosten entstehen oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Recycling im IT-Betrieb ein Beitrag zum Umweltschutz?', 2, '[{"text": "Ja", "correct": true, "because": "Reduziert Ressourcenverbrauch"}, {"text": "Nein", "correct": false, "because": "Umweltschutz wird gefördert"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt das Recycling im IT-Betrieb?', 2, '[{"text": "Kreislaufwirtschaftsgesetz (KrWG)", "correct": true, "because": "Regelt Abfallwirtschaft"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}, {"text": "BBiG", "correct": false, "because": "Regelt Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Recycling im IT-Betrieb?', 3, '[{"text": "Wiederverwertung von Ressourcen", "correct": true, "because": "Kernziel des Recyclings"}, {"text": "Erhöhung der Produktionskosten", "correct": false, "because": "Kein Ziel"}, {"text": "Vermeidung von Hardware", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört zum Recycling im IT-Betrieb?', 2, '[{"text": "Rücknahme alter Geräte", "correct": true, "because": "Teil des ElektroG"}, {"text": "Verbrennung von Abfällen", "correct": false, "because": "Keine Wiederverwertung"}, {"text": "Ignorieren von Papierabfällen", "correct": false, "because": "Kein Recycling"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz kann fehlendes Recycling im IT-Betrieb haben?', 3, '[{"text": "Bußgelder wegen Verstößen", "correct": true, "because": "KrWG-Verstöße strafbar"}, {"text": "Geringere Arbeitszeit", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Bessere Produktivität", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist im IT-Betrieb für die Umsetzung von Recycling verantwortlich?', 2, '[{"text": "Das Management", "correct": true, "because": "Verantwortlich für Prozesse"}, {"text": "Die Auszubildenden", "correct": false, "because": "Nur mitwirkend"}, {"text": "Die Kunden", "correct": false, "because": "Keine Rolle"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Materialien können im IT-Betrieb recycelt werden?', 4, '[{"text": "Alte Computer", "correct": true, "because": "ElektroG-relevant"}, {"text": "Papierabfälle", "correct": true, "because": "Wiederverwertbar"}, {"text": "Lebensmittelreste", "correct": false, "because": "Weniger relevant"}, {"text": "Batterien", "correct": true, "because": "Sonderabfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Recycling im IT-Betrieb?', 3, '[{"text": "Reduzierung der Abfallmenge", "correct": true, "because": "Weniger Müll"}, {"text": "Ressourcenschonung", "correct": true, "because": "Wiederverwertung"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Umweltschutz", "correct": true, "because": "Nachhaltigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen regeln das Recycling im IT-Betrieb?', 4, '[{"text": "Kreislaufwirtschaftsgesetz (KrWG)", "correct": true, "because": "Regelt Abfallwirtschaft"}, {"text": "Elektro- und Elektronikgerätegesetz (ElektroG)", "correct": true, "because": "Für IT-Geräte"}, {"text": "Arbeitsschutzgesetz (ArbSchG)", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Batteriegesetz (BattG)", "correct": true, "because": "Für Batterien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat fehlendes Recycling im IT-Betrieb?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen KrWG"}, {"text": "Umweltbelastung", "correct": true, "because": "Mehr Abfall"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Kein Effekt"}, {"text": "Schlechtes Image", "correct": true, "because": "Fehlende Nachhaltigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen das Recycling im IT-Betrieb?', 3, '[{"text": "Trennung von Abfällen", "correct": true, "because": "Fördert Wiederverwertung"}, {"text": "Rücknahmeprogramme für Geräte", "correct": true, "because": "ElektroG-konform"}, {"text": "Verbrennung aller Abfälle", "correct": false, "because": "Keine Wiederverwertung"}, {"text": "Sammlung von Batterien", "correct": true, "because": "Sonderabfallregelung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Recycling reduziert die Abfallmenge. b) Es ist im IT-Betrieb optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (KrWG-Pflicht)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das ElektroG regelt das Recycling von IT-Geräten. b) Recycling erhöht die Umweltbelastung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (schützt Umwelt)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Recycling kann Kosten verursachen. b) Es hat keinen Einfluss auf Ressourcen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Ressourcenschonung)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Abfalltrennung unterstützt Recycling. b) Das Management ist nicht verantwortlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Management zuständig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Recycling schützt die Umwelt. b) Fehlendes Recycling kann Bußgelder nach sich ziehen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Umweltschutz, b) KrWG-Sanktionen"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
